using System;using System.Reflection;using Colossal.Mathematics;using Unity.Mathematics;
class Test52GlobalSurfaces {
static int n;static Assembly a;static BindingFlags f=BindingFlags.Static|BindingFlags.NonPublic;static void Check(bool ok,string m){if(!ok)throw new Exception(m);n++;}
static void Main(){a=Assembly.LoadFrom("MedianGrassReplacement.dll");var policy=a.GetType("MedianGrassReplacement.Systems.GlobalSurfacePolicy").GetMethod("Kind",f);string shader="BH/NetCompositionMeshLitShader";
foreach(var name in new[]{"Batch (RoadAsphalt_123)","Batch (Tarmac)"})Check((int)policy.Invoke(null,new object[]{name,shader})==1,"network road material recognized");foreach(var name in new[]{"Batch (SidewalkConcrete)","Batch (Pavement)"})Check((int)policy.Invoke(null,new object[]{name,shader})==2,"network sidewalk recognized");foreach(var name in new[]{"RoadGrass","RoadAsphalt Decal","RoadAsphalt Marking","RoadAsphalt Curb","Rail","Building Concrete"})Check((int)policy.Invoke(null,new object[]{name,shader})==0,"excluded or unrecognized material preserved");Check((int)policy.Invoke(null,new object[]{"RoadAsphalt","BuildingShader"})==0,"same name on building shader excluded");
var curve=new Bezier4x3(new float3(0,0,0),new float3(0,0,10),new float3(0,0,20),new float3(0,0,30));var limits=a.GetType("MedianGrassReplacement.Systems.ParkingSetback").GetMethod("TryLimits",f);
foreach(float distance in new[]{2f,4f,5f,8f}){object[] args={curve,0f,1f,true,true,distance,0f,0f};Check((bool)limits.Invoke(null,args),"setback valid");float first=(float)args[6],last=(float)args[7];Check(Math.Abs(MathUtils.Length(MathUtils.Cut(curve,new float2(0,first)))-distance)<.002,"start hatch length exact");Check(Math.Abs(MathUtils.Length(MathUtils.Cut(curve,new float2(last,1)))-distance)<.002,"end hatch length exact");}
Check(a.GetType("MedianGrassReplacement.Systems.HatchExclusionPolicy")==null,"bay clipping experiment removed");Check(a.GetType("MedianGrassReplacement.Systems.GlobalSurfaceMaterialSystem").GetInterface("IPreSerialize")==null,"global renderer does not serialize network edits");var role=a.GetType("MedianGrassReplacement.Systems.HighwayNodePaintPolicy").GetMethod("Role",f);
Check((int)role.Invoke(null,new object[]{"NA Highway Edge Line",false})==2,"highway shoulder role");Check((int)role.Invoke(null,new object[]{"Car Center Line",false})==1,"highway center role");Check((int)role.Invoke(null,new object[]{"Car Lane Line",false})==3,"highway divider role");Check((int)role.Invoke(null,new object[]{"Car Lane Line",true})==1,"opposing boundary takes precedence");Check((int)role.Invoke(null,new object[]{"Crosswalk",false})==0,"crossing not treated as highway line");Console.WriteLine(n+" Test52 global material and exact hatch-length checks passed");}}
